using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;using MapTunnels.EditorTools;using MapTunnels;
public static class Shelf215Checks{
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static string Out=>Path.Combine(Root,"Evidence215");
 [Serializable]class Inputs{public string before,after;}[Serializable]class LoadRow{public string stage;public int count,visible,meshes,materials,textures,triangles;public long meshBytes;public double cpuMedianMs;}
 [Serializable]class Report{public bool pass,other19Exact,other19AtlasShared,prefabReload,sceneReload,boundsExact,colliderUnchanged;public int formalBefore,formalAfter,placedBefore,placedAfter,triBefore,triAfter;public string beforeFolder,afterFolder;public LoadRow[] loads;public string[] limits;}
 static void Check(bool b,string m){if(!b)throw new Exception(m);}static void Empty(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.13f,.14f,.15f);RenderSettings.skybox=null;RenderSettings.reflectionIntensity=0;Shader.SetGlobalVector("_TDPineWind",Vector4.zero);}
 static Camera Cam(){var c=new GameObject("shelf209-offscreen").AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.035f,.04f,.045f);c.fieldOfView=45;c.nearClipPlane=.025f;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;return c;}
 static void Shot(Camera c,string name){var t=Shared117Review.Image(c,1100,800);File.WriteAllBytes(Path.Combine(Out,name+".png"),t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}
 static string Snap(GameObject root){return string.Join("\n",root.GetComponentsInChildren<MeshFilter>().OrderBy(x=>x.name).Select(x=>x.name+"|"+x.transform.localPosition.ToString("F7")+"|"+x.transform.localRotation.ToString("F7")+"|"+x.transform.localScale.ToString("F7")+"|"+ColliderSnapshot109.MeshHash(x.sharedMesh)+"|"+JsonUtility.ToJson(new MeshData{n=x.sharedMesh.normals,uv=x.sharedMesh.uv,c=x.sharedMesh.colors})+"|"+AssetDatabase.GetAssetPath(x.GetComponent<Renderer>().sharedMaterial)+"|"+x.GetComponent<Renderer>().sharedMaterial.IsKeywordEnabled("SMALL_PROP_LOCAL_LIGHTS")));}
 [Serializable]class MeshData{public Vector3[] n;public Vector2[] uv;public Color[] c;}
 public static void Run(){Directory.CreateDirectory(Out);try{
  Empty();var rp=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset");Check(rp,"pipeline");GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;
  var input=JsonUtility.FromJson<Inputs>(File.ReadAllText(Path.Combine(Root,"Input209.json")));
  var old=MapSharedPropsBuilder.Build(input.before);Check(old.prefabs.Count==20&&old.placed==20&&old.skipped==0,"before formal20");UnityEngine.Object.DestroyImmediate(old.root);
  var cur=MapSharedPropsBuilder.Build(input.after);Check(cur.prefabs.Count==20&&cur.placed==20&&cur.skipped==0,"after formal20");
  foreach(var kv in cur.prefabs){var a=old.prefabs[kv.Key].GetComponent<MeshFilter>().sharedMesh;var b=kv.Value.GetComponent<MeshFilter>().sharedMesh;
   Check(old.prefabs[kv.Key].GetComponentsInChildren<Collider>().Length==0&&kv.Value.GetComponentsInChildren<Collider>().Length==0,"visual-only collider unchanged");
   if(kv.Key!="cnd015")Check(a==b&&a.normals.SequenceEqual(b.normals)&&a.uv.SequenceEqual(b.uv)&&a.colors.SequenceEqual(b.colors),"other19 shared exact "+kv.Key);
   var ma=old.prefabs[kv.Key].GetComponent<Renderer>().sharedMaterial;var mb=kv.Value.GetComponent<Renderer>().sharedMaterial;Check(ma.shader==mb.shader&&mb.IsKeywordEnabled("SMALL_PROP_LOCAL_LIGHTS")&&!ShaderUtil.ShaderHasError(mb.shader),"shader/keyword");if(kv.Key!="cnd015")Check(ma.GetTexture("_BaseMap")==mb.GetTexture("_BaseMap"),"old atlas shared");else Check(mb.GetTexture("_BaseMap").width==128&&mb.GetTexture("_BaseMap").height==128,"new small map");
  }
  var before=old.prefabs["cnd015"];var after=cur.prefabs["cnd015"];var bm=before.GetComponent<MeshFilter>().sharedMesh;var am=after.GetComponent<MeshFilter>().sharedMesh;Check(bm.triangles.Length==72&&am.triangles.Length==516,"tri24/172");Check((bm.bounds.min-am.bounds.min).magnitude<1e-6f&&(bm.bounds.max-am.bounds.max).magnitude<1e-6f,"legacy bounds");Check(am.normals.All(n=>Mathf.Abs(n.magnitude-1)<.001f),"unit normals");
  string snap=Snap(cur.root);string group=cur.assetDirectory+"/shelf209-group.prefab";var saved=PrefabUtility.SaveAsPrefabAsset(cur.root,group);AssetDatabase.SaveAssets();UnityEngine.Object.DestroyImmediate(cur.root);var restored=(GameObject)PrefabUtility.InstantiatePrefab(saved);Check(Snap(restored)==snap,"prefab reload");
  string scene=cur.assetDirectory+"/shelf209.unity";EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),scene);Empty();EditorSceneManager.OpenScene(scene);var candidates=UnityEngine.Object.FindObjectsByType<GameObject>(FindObjectsSortMode.None).Where(x=>x.transform.parent==null&&PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(x)==group).ToArray();Check(candidates.Length==1&&Snap(candidates[0])==snap,"GUID/path scene reload");
  foreach(var stage in new[]{"before","after"}){var prefab=stage=="before"?before:after;Studio(prefab,stage);Field(prefab,stage);}
  var loads=new List<LoadRow>();loads.AddRange(Load(before,"before"));loads.AddRange(Load(after,"after"));
  var report=new Report{pass=true,other19Exact=true,other19AtlasShared=true,prefabReload=true,sceneReload=true,boundsExact=true,colliderUnchanged=true,formalBefore=20,formalAfter=20,placedBefore=20,placedAfter=20,triBefore=24,triAfter=172,beforeFolder=old.assetDirectory,afterFolder=cur.assetDirectory,loads=loads.ToArray(),limits=new[]{"Cave-decoration20 formal route, not whole catalog reimport","Existing cave decorative prefabs are visual-only; Web existing IDs/placement collider tested separately","GPU/mobile/Player not measured","CPU Camera.Render samples are diagnostic only","Manually mounted on existing timber; no automatic wall snapping"}};
  File.WriteAllText(Path.Combine(Out,"checks.json"),JsonUtility.ToJson(report,true));Empty();AssetDatabase.SaveAssets();EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(Path.Combine(Out,"error.txt"),e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
 static void Studio(GameObject prefab,string stage){Empty();var o=(GameObject)PrefabUtility.InstantiatePrefab(prefab);o.transform.position=Vector3.up*.4f;
  var post=GameObject.CreatePrimitive(PrimitiveType.Cube);post.transform.position=new Vector3(0,.2f,-.19f);post.transform.localScale=new Vector3(.69f,.8f,.08f);var mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.color=new Color(.16f,.13f,.10f);post.GetComponent<Renderer>().sharedMaterial=mat;
  var c=Cam();var sun=new GameObject("review-main").AddComponent<Light>();sun.type=LightType.Directional;sun.shadows=LightShadows.Soft;var point=new GameObject("review-point").AddComponent<Light>();point.type=LightType.Point;point.range=5;point.intensity=4;point.color=new Color(1,.72f,.42f);point.transform.position=new Vector3(.5f,1,1);
  foreach(string view in new[]{"normal","close","side","under","opposite","dark","off"}){sun.intensity=view=="dark"||view=="off"?0:1.3f;sun.transform.rotation=Quaternion.Euler(45,view=="opposite"?150:-30,0);point.enabled=view=="dark";RenderSettings.ambientLight=view=="off"?Color.black:view=="dark"?new Color(.025f,.03f,.035f):new Color(.13f,.14f,.15f);
   var target=new Vector3(0,.2f,0);c.transform.position=target+(view=="normal"?new Vector3(.5f,7,5):view=="side"?new Vector3(1.6f,.25f,.3f):view=="under"?new Vector3(.6f,-.35f,1.8f):new Vector3(1.1f,.75f,1.8f));c.transform.LookAt(target);Shot(c,stage+"-studio-"+view);
  }UnityEngine.Object.DestroyImmediate(mat);
 }
 static void Field(GameObject prefab,string stage){Empty();RenderSettings.ambientLight=new Color(.08f,.09f,.10f);var tunnel=MapTunnelBuilder.Build(Path.Combine(Root,"Input123Mine"),null,null,"Shelf209");Check(tunnel.built,"existing mine");var timber=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/MapSharedPropsGenerated/Pilot 26/small-mine_timber_frame.prefab");Check(timber,"existing timber prefab");var support=(GameObject)PrefabUtility.InstantiatePrefab(timber);support.transform.position=new Vector3(12,0,10.5f);
  var o=(GameObject)PrefabUtility.InstantiatePrefab(prefab);o.transform.position=new Vector3(11.21f,1.6f,10.5f);o.transform.rotation=Quaternion.Euler(0,90,0);
  var c=Cam();var hero=new GameObject("anchor").transform;hero.position=new Vector3(12,0,10.5f);var cut=tunnel.root.GetComponent<MapTunnelCutaway>();cut.hero=hero;cut.viewCamera=c;
  foreach(string view in new[]{"normal","close","opposite"}){var target=o.transform.position+Vector3.down*.2f;c.transform.position=view=="normal"?hero.position+new Vector3(0,9,-6.3f):target+(view=="opposite"?new Vector3(2.1f,.5f,1.1f):new Vector3(2.1f,.5f,-1.1f));c.transform.LookAt(target);typeof(MapTunnelCutaway).GetMethod("LateUpdate",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(cut,null);Shot(c,stage+"-mine-"+view);}
 }
 static IEnumerable<LoadRow> Load(GameObject prefab,string stage){Empty();var c=Cam();var sun=new GameObject("main").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1;sun.transform.rotation=Quaternion.Euler(45,-30,0);var rows=new List<LoadRow>();foreach(int count in new[]{9,225}){int side=(int)Math.Sqrt(count);var objects=new List<GameObject>();for(int i=0;i<count;i++){var o=(GameObject)PrefabUtility.InstantiatePrefab(prefab);o.transform.position=new Vector3((i%side)*1.3f,.4f,(i/side)*1.3f);objects.Add(o);}c.transform.position=new Vector3((side-1)*.65f,side*1.6f,(side-1)*.65f+side*.9f);c.transform.LookAt(new Vector3((side-1)*.65f,.2f,(side-1)*.65f));var planes=GeometryUtility.CalculateFrustumPlanes(c);var rs=objects.SelectMany(o=>o.GetComponentsInChildren<Renderer>()).ToArray();var meshes=objects.SelectMany(o=>o.GetComponentsInChildren<MeshFilter>()).Select(x=>x.sharedMesh).Distinct().ToArray();var mats=rs.Select(x=>x.sharedMaterial).Distinct().ToArray();var textures=mats.SelectMany(m=>m.GetTexturePropertyNames().Select(m.GetTexture)).Where(t=>t).Distinct().ToArray();var rt=new RenderTexture(640,360,24);c.targetTexture=rt;for(int i=0;i<3;i++)c.Render();var times=new List<double>();for(int i=0;i<9;i++){var sw=System.Diagnostics.Stopwatch.StartNew();c.Render();sw.Stop();times.Add(sw.Elapsed.TotalMilliseconds);}times.Sort();c.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);rows.Add(new LoadRow{stage=stage,count=count,visible=rs.Count(x=>GeometryUtility.TestPlanesAABB(planes,x.bounds)),meshes=meshes.Length,materials=mats.Length,textures=textures.Length,triangles=meshes.Sum(m=>m.triangles.Length/3),meshBytes=meshes.Sum(m=>(long)m.vertexCount*44+m.triangles.Length*2),cpuMedianMs=times[4]});Check(meshes.Length==1&&mats.Length==1&&textures.Length==1,"shared references");foreach(var o in objects)UnityEngine.Object.DestroyImmediate(o);}return rows;}
}
